"use client";

import React, { useState, useEffect, useRef } from 'react';
import { motion } from 'framer-motion';

const chars = '!<>-_\\\\/[]{}ÔÇö=+*^?#________';

const ScrambleText = ({ text }: { text: string }) => {
  const [displayText, setDisplayText] = useState(text);
  const [isHovering, setIsHovering] = useState(false);
  const intervalRef = useRef<NodeJS.Timeout | null>(null);

  useEffect(() => {
    if (isHovering) {
      let iteration = 0;
      intervalRef.current = setInterval(() => {
        setDisplayText(
          text.split('').map((letter, index) => {
            if (index < iteration) {
              return text[index];
            }
            return chars[Math.floor(Math.random() * chars.length)];
          }).join('')
        );
        iteration += 1 / 3;
        if (iteration >= text.length) {
          clearInterval(intervalRef.current as NodeJS.Timeout);
          setDisplayText(text);
        }
      }, 30);
    } else {
      setDisplayText(text);
      if (intervalRef.current) clearInterval(intervalRef.current);
    }
    return () => {
      if (intervalRef.current) clearInterval(intervalRef.current);
    };
  }, [isHovering, text]);

  return (
    <span 
      className="inline-block"
      onMouseEnter={() => setIsHovering(true)}
      onMouseLeave={() => setIsHovering(false)}
    >
      {displayText}
    </span>
  );
};

export default function BookingCTA() {
  return (
    <section className="relative w-full min-h-[60vh] flex flex-col items-center justify-center py-20 px-6 bg-black z-20 overflow-hidden">
      {/* Grid background / Tech pattern */}
      <div className="absolute inset-0 opacity-10 bg-[radial-gradient(ellipse_at_center,_var(--tw-gradient-stops))] from-brand-red via-black to-black pointer-events-none" />
      <div className="absolute inset-0 border border-silver/30 pointer-events-none" />

      <div className="relative z-10 w-full max-w-2xl text-center flex flex-col items-center">

        <motion.h2 
          className="text-4xl md:text-6xl font-display font-bold text-silver uppercase mb-12 animate-flicker"
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
        >
          // <span className="text-brand-red">BOOKING</span> //
        </motion.h2>

        <div className="flex flex-col gap-6 w-full max-w-md">
          {/* WhatsApp Button */}
          <a 
            href="https://wa.me/573234470562" 
            target="_blank" 
            rel="noopener noreferrer"
            className="cta-cyber-btn group w-full text-center"
          >
            <span className="cta-cyber-btn__text font-display text-lg">
              <ScrambleText text="CONTACTO DIRECTO (WhatsApp)" />
            </span>
            <span className="cta-cyber-btn__glitch">CONTACTO DIRECTO (WhatsApp)</span>
          </a>

          {/* Instagram Button */}
          <a 
            href="https://www.instagram.com/paulgzco/" 
            target="_blank" 
            rel="noopener noreferrer"
            className="cta-cyber-btn group w-full text-center hover:!bg-silver hover:!text-black"
          >
            <span className="cta-cyber-btn__text font-display text-lg">
              <ScrambleText text="INSTAGRAM" />
            </span>
            <span className="cta-cyber-btn__glitch text-brand-red">INSTAGRAM</span>
          </a>
        </div>

      </div>
    </section>
  );
}

