/**
 * VideoThumbnail ÔÇö captures a single frame from a video at seekTime
 * and renders it as a static <img> poster via an offscreen canvas.
 */
function VideoThumbnail({ src, isSelected, className }: { src: string; isSelected: boolean; className: string }) {
    const [poster, setPoster] = useState<string | null>(null);
    const attempted = useRef(false);

    const capture = useCallback(() => {
        if (attempted.current) return;
        attempted.current = true;

        const video = document.createElement("video");
        video.muted = true;
        video.playsInline = true;
        video.preload = "metadata";
        video.src = src;

        video.addEventListener("loadeddata", () => {
            video.currentTime = Math.min(0.5, video.duration || 0.5);
        });

        video.addEventListener("seeked", () => {
            try {
                const canvas = document.createElement("canvas");
                canvas.width = video.videoWidth || 320;
                canvas.height = video.videoHeight || 180;
                const ctx = canvas.getContext("2d");
                if (ctx) {
                    ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
                    setPoster(canvas.toDataURL("image/jpeg", 0.7));
                }
            } catch { /* CORS or security ÔÇö fall through to video fallback */ }
            video.src = ""; // release memory
        });

        video.load();
    }, [src]);

    useEffect(() => { capture(); }, [capture]);

    if (poster) {
        return (
            <img
                src={poster}
                alt={extractFilename(src)}
                className={className}
            />
        );
    }

    // Fallback: show the <video> itself while the canvas capture is loading
    return (
        <video
            src={`${src}#t=0.5`}
            className={className}
            muted
            playsInline
            preload="metadata"
        />
    );
}

